"""Freeze finite step6 physical capacity and orthogonal synth controls."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,sys
R=Path.cwd();sys.path.insert(0,str(R));B=R/'build/step6-integration-20261031'
from experiments.arithmetic_dse.budget import POLICY,usage
from experiments.arithmetic_dse.platforms import profile
from experiments.arithmetic_dse.sdc import VERSION
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
items={x['name']:x for x in json.loads((B/'fixtures-v3/items.json').read_text())};tasks=[]
for name,kernel,top in [('UDR_128_C','udr_unsigned_128','Step6UDR128'),('F2_C','fp32_serial','Step6FP2')]:
 item=items[name];case=item['case'];report=B/'generated-final'/(name+'.json');r=json.loads(report.read_text());directory=B/'capacity-inputs'/name;directory.mkdir(parents=True,exist_ok=False)
 text=(B/'generated-final'/(name+'.sv')).read_text();declarations=['input logic clk,rstn,iv']+[f'input logic [{w-1}:0] {p}' for p,w in case['inputs'].items()]+['output logic ov']+[f'output logic [{w-1}:0] {p}' for p,w in case['outputs'].items()]
 text+='\nmodule '+top+'('+','.join(declarations)+');\nwire valid;\n'+''.join(f'wire [{w-1}:0] raw_{p};\n' for p,w in case['outputs'].items())+name+' core(.clk(clk),.rstn(rstn),.iv(iv),.ov(valid),'+','.join(f'.{p}({p})' for p in case['inputs'])+','+','.join(f'.{p}(raw_{p})' for p in case['outputs'])+');\nalways_ff @(posedge clk)begin if(!rstn)begin ov<=0;'+''.join(f'{p}<={w}\'d{item["reset_outputs"][p]};' for p,w in case['outputs'].items())+'end else begin ov<=valid;if(valid)begin '+''.join(f'{p}<=raw_{p};' for p in case['outputs'])+'end end end\nendmodule\n'
 rtl=directory/'input.sv';rtl.write_text(text)
 for suffix,abc,period,stage,role in [('capacity',1500,1500,'grt','bounded_capacity'),('abc0750',750,1500,'synth','ABC_only_sensitivity'),('sdc3000',1500,3000,'synth','SDC_with_frozen_proportional_IO_sensitivity')]:
  tasks.append({'id':'asap7-step6-'+kernel+'-'+suffix+'-v1','platform':'asap7','profile_sha256':profile('asap7')['profile_sha256'],'kernel':kernel,'top':top,'rtl':str(rtl),'rtl_sha256':sha(rtl),'compiler_report':str(report),'compiler_report_sha256':sha(report),'graph_sha256':r['graph_sha256'],'schedule_sha256':r['schedule_sha256'],'L':item['L'],'II':1,'selected_candidate':r['selection']['selected_candidate'],'period_ps':period,'abc_target_ps':abc,'stage':stage,'purpose':'physical_recheck','diagnostic_role':role,'constraints_sha256':sha(R/'experiments/arithmetic_dse/backend/constraints.sdc'),'sdc_contract_version':VERSION,'IO_delay_policy':'max=0.2*SDC_period; min=0; explicitly coupled when SDC changes','data_role':'formal_case_capacity_and_sensitivity_diagnostic; prohibited_as_training_or_target_label'})
state=json.loads((R/'experiments/arithmetic/backend_usage.json').read_text());live=usage(state['entries']);policy=json.loads(POLICY.read_text())['resources'];wall=6*300+2*1200+1800;cpu=wall*2
assert not live['pending'];assert live['synth']+6<=policy['max_synthesis_calls'] and live['grt']+2<=policy['max_global_route_calls'];assert live['walltime_s']+wall<=policy['max_global_walltime_h']*3600 and live['CPU_time_s']+cpu<=policy['max_tool_CPU_time_h']*3600
admission={'id':'step6-bounded-capacity-sensitivity-v1','purpose':'arithmetic_capacity_only','created_at':datetime.now(timezone.utc).isoformat(),'policy_sha256':sha(POLICY),'starting_usage_live':live,'tasks':tasks,'call_caps':{'synth':6,'grt':2,'final':0},'threads':2,'memory_limit_MiB':8192,'synthesis_timeout_s':300,'post_synthesis_through_grt_timeout_s':1200,'support_envelope':{'walltime_s':1800,'CPU_time_s':3600},'worst_case_walltime_s':wall,'CPU_envelope_s':cpu,'automatic_retries':0,'global_budget_changed':False,'bulk_training_or_main_matrix_authorized':False,'target_formula_labels_created':False,'scope':'two fixed selected C implementations; one baseline synth->grt each plus two synth-only axis controls each; no original comparison, final or selection from PPA','timing_verdict':'actual full constrained slack/coverage per stage; core same-clock period_min diagnostic only','funding_note':'one shared global v5 ledger; physical failures and support fully retained'}
path=B/'capacity-admission.json';assert not path.exists();path.write_text(json.dumps(admission,indent=2)+'\n');print(json.dumps({'tasks':len(tasks),'starting_usage':live,'walltime_envelope_s':wall,'CPU_envelope_s':cpu,'call_caps':admission['call_caps']},indent=2))
